local MandolinMaker = {}
local PRODUCTS = {
    simple_wooden_mandolin = { name = "Preprosta lesena mandolina", woodCost = 2, ropeCost = 1, time = 4, cost = 50, music = 22, happiness = 2, description = "Preprosta lesena mandolina za potujoče pevce." },
    inlaid_rosewood_mandolin = { name = "Vložkana palisandrova mandolina", woodCost = 3, leatherCost = 1, ropeCost = 1, time = 6, cost = 140, music = 38, happiness = 2, prestige = 2, description = "Vložkana palisandrova mandolina za trgovce." },
    bronze_string_mandolin = { name = "Bronastovrvena mandolina", woodCost = 3, bronzeCost = 2, leatherCost = 1, time = 9, cost = 320, music = 52, happiness = 3, prestige = 6, description = "Mandolina z bronastimi strunami za plemiče." },
    silver_band_mandolin = { name = "Srebrnopasna mandolina", woodCost = 3, silverCost = 2, bronzeCost = 1, leatherCost = 1, time = 13, cost = 760, music = 66, happiness = 4, prestige = 14, description = "Srebrnopasna mandolina za visoke plemiče." },
    gold_trimmed_mandolin = { name = "Zlatookrasna mandolina", woodCost = 4, goldCost = 2, silverCost = 1, bronzeCost = 1, leatherCost = 1, jewelCost = 1, time = 17, cost = 1700, music = 80, happiness = 6, prestige = 27, description = "Zlatookrasna mandolina z draguljem za visoko plemstvo." },
    royal_grand_mandolin = { name = "Kraljevski velika mandolina", woodCost = 5, goldCost = 3, silverCost = 2, bronzeCost = 1, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 3900, music = 95, happiness = 12, prestige = 58, description = "Velika kraljevska mandolina z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    mandolin_workshop = { name = "Mandolinska delavnica", cost = { gold = 240, wood = 120, stone = 80, leather = 6 }, upkeep = 5, qualityBonus = 5 },
    stringed_loft = { name = "Strunska podstrešje", cost = { gold = 820, wood = 260, stone = 240, bronze = 6, leather = 8 }, upkeep = 19, qualityBonus = 18 },
    master_luthier_atelier = { name = "Mojstrski lutar atelje", cost = { gold = 2300, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 52, qualityBonus = 30 },
    royal_mandolin_palace = { name = "Kraljevska mandolinska palača", cost = { gold = 9500, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 50 },
}
MandolinMaker.woodStock = 16; MandolinMaker.leatherStock = 12; MandolinMaker.ropeStock = 10; MandolinMaker.bronzeStock = 8; MandolinMaker.silverStock = 6; MandolinMaker.goldStock = 6; MandolinMaker.jewelStock = 4; MandolinMaker.pearlStock = 4
MandolinMaker.productStock = {}; MandolinMaker.buildings = {}; MandolinMaker.maker = nil; MandolinMaker.activeMaking = {}; MandolinMaker.totalProducts = 0; MandolinMaker.dayTimer = 0
function MandolinMaker.init() MandolinMaker.woodStock=16; MandolinMaker.leatherStock=12; MandolinMaker.ropeStock=10; MandolinMaker.bronzeStock=8; MandolinMaker.silverStock=6; MandolinMaker.goldStock=6; MandolinMaker.jewelStock=4; MandolinMaker.pearlStock=4; MandolinMaker.productStock={}; MandolinMaker.buildings={}; MandolinMaker.maker=nil; MandolinMaker.activeMaking={}; MandolinMaker.totalProducts=0; MandolinMaker.dayTimer=0; print("[MandolinMaker] Royal Mandolin Maker System initialized (6 products, 4 buildings)") end
function MandolinMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MandolinMaker.maker={name=n or ("Mandolinar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mandolinar najet: %s (spretnost: %d)",MandolinMaker.maker.name,s),"success") end; return true end
function MandolinMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MandolinMaker.build(id) local ok,e=MandolinMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MandolinMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MandolinMaker.getQualityBonus() local b=0; for _,bd in ipairs(MandolinMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MandolinMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and MandolinMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MandolinMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.ropeCost and MandolinMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.bronzeCost and MandolinMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.silverCost and MandolinMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MandolinMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MandolinMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MandolinMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MandolinMaker.buildings==0 then return false,"Potrebna mandolinska delavnica" end; if not MandolinMaker.maker then return false,"Potreben mandolinar" end; return true end
function MandolinMaker.make(pt,qty) qty=qty or 1; local ok,e=MandolinMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then MandolinMaker.woodStock=MandolinMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MandolinMaker.leatherStock=MandolinMaker.leatherStock-d.leatherCost*qty end; if d.ropeCost then MandolinMaker.ropeStock=MandolinMaker.ropeStock-d.ropeCost*qty end; if d.bronzeCost then MandolinMaker.bronzeStock=MandolinMaker.bronzeStock-d.bronzeCost*qty end; if d.silverCost then MandolinMaker.silverStock=MandolinMaker.silverStock-d.silverCost*qty end; if d.goldCost then MandolinMaker.goldStock=MandolinMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MandolinMaker.jewelStock=MandolinMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MandolinMaker.pearlStock=MandolinMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MandolinMaker.maker then t=math.max(1,t-math.floor(MandolinMaker.maker.skill/13)) end; table.insert(MandolinMaker.activeMaking,{id="mandolin_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,music=d.music or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MandolinMaker.completeMaking(m) local q=1.0+(MandolinMaker.getQualityBonus()/100); if MandolinMaker.maker then q=q+(MandolinMaker.maker.skill/150) end; q=math.min(2.4,q); MandolinMaker.productStock[m.productType]=(MandolinMaker.productStock[m.productType] or 0)+m.quantity; MandolinMaker.totalProducts=MandolinMaker.totalProducts+m.quantity; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if MandolinMaker.maker then MandolinMaker.maker.itemsMade=MandolinMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MandolinMaker.maker.skill=math.min(100,MandolinMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mandolina izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"mandolin.completed",{productName=m.productName,music=m.music,prestige=m.prestige,happiness=m.happiness}) end end
function MandolinMaker.update(dt) if not _G.state then return end; MandolinMaker.dayTimer=MandolinMaker.dayTimer+dt; if MandolinMaker.dayTimer>=30 then MandolinMaker.dayTimer=0; for i=#MandolinMaker.activeMaking,1,-1 do local m=MandolinMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MandolinMaker.completeMaking(m); table.remove(MandolinMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MandolinMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MandolinMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MandolinMaker.getStats() return {woodStock=MandolinMaker.woodStock,leatherStock=MandolinMaker.leatherStock,ropeStock=MandolinMaker.ropeStock,bronzeStock=MandolinMaker.bronzeStock,silverStock=MandolinMaker.silverStock,goldStock=MandolinMaker.goldStock,jewelStock=MandolinMaker.jewelStock,pearlStock=MandolinMaker.pearlStock,productStock=MandolinMaker.productStock,numBuildings=#MandolinMaker.buildings,hasMaker=MandolinMaker.maker~=nil,makerName=MandolinMaker.maker and MandolinMaker.maker.name or "—",makerSkill=MandolinMaker.maker and MandolinMaker.maker.skill or 0,activeMaking=#MandolinMaker.activeMaking,totalProducts=MandolinMaker.totalProducts} end
return MandolinMaker
